import Rocket from '@/assets/images/img_rocket@2x.png'
import { useGetPumpToken } from '@/hook/pump/useGetPumpToken'
import { PumpToken } from '@/type/pump'
import Block from '@cetus/design/src/components/common/Block'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import { useJump2Dex } from '@cetus/hooks/src/useJump2Dex'
import useTransaction from '@cetus/hooks/src/useTransaction'
import { CommonTypeInfo } from '@cetus/types'
import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import { Box, Button, HStack, Image, Text, VStack } from '@chakra-ui/react'
import { SUI_TYPE_ARG } from '@mysten/sui/utils'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'

type MigratedProps = {
  token?: PumpToken
}

function Migrated(props: MigratedProps) {
  const navigate = useNavigate()
  const { token } = props
  const { pumpSdk, clmmSdk } = useInitSDK()
  const [loading, setLoading] = useState(false)
  const { refreshPumpToken } = useGetPumpToken()
  const { signAndExecuteTransaction } = useTransaction()
  const { jump2Swap, jump2Pool } = useJump2Dex()

  const doBurnClick = async () => {
    const clmm_pool_id = token!.TokenDetail.clmm_pool
    setLoading(true)

    try {
      const tx = pumpSdk.pumpModule.buildBurnLpPayload({
        bonding_curve_id: token!.token_info_id,
        clmm_pool_id,
        clmm_coin_type_a: token!.coin_type,
        clmm_coin_type_b: SUI_TYPE_ARG,
        token_coin_type: token!.coin_type
      })

      const res = await signAndExecuteTransaction(tx, {
        getShowInfo: status => {
          const info: CommonTypeInfo = {
            iconUrl: token!.TokenDetail.image,
            toastTitleText: `LP burn`,
            modalTitleText: `LP burn`,
            modalDescriptionText: `LP burn`
          }
          if (status === 'success') {
            info.toastTitleText = `LP burn successful`
            info.modalDescriptionText = `LP burn successful`
          }

          if (status === 'rejected') {
            info.toastTitleText = `LP burn failed`
            info.modalDescriptionText = `LP burn failed`
          }

          return info
        }
      })

      if (token) {
        refreshPumpToken(token!.TokenDetail.coin_type)
      }
    } catch (error) {
      console.log('🚀 ~ file: Completed.tsx:38 ~ doMigrateClick ~ error:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Block p="16px">
      <VStack mt="16px" gap="40px">
        <VStack gap="0px">
          <Image src={Rocket} w="200px" h="200px" />
          <Text h="16px" lineHeight="16px" fontSize="16px" color="text_caption">
            Token Migrated to Cetus DEX
          </Text>
        </VStack>
        <VStack gap="20px" w="100%">
          <HStack p="0 30px" gap="14px" w="100%">
            <Button flex="1" variant="outline" fontWeight="500" fontSize="14px" onClick={() => jump2Pool(token?.TokenDetail?.clmm_pool || '')}>
              Add Liquidity
            </Button>
            <Button flex="1" fontWeight="500" fontSize="14px" onClick={() => jump2Swap(SUI_TYPE_ARG, token?.coin_type || '')}>
              Trade Now
            </Button>
          </HStack>
          {token?.status === BondingCurveStatus.MIGRATED ? (
            <Button
              isLoading={loading}
              variant="unstyled"
              color="primary"
              fontSize="14px"
              w="50%"
              loadingText="LP Burn >"
              onClick={() => doBurnClick()}
            >
              {'LP Burn >'}
            </Button>
          ) : (
            <Box h="40px" />
          )}
        </VStack>
      </VStack>
    </Block>
  )
}

export default Migrated
