import { usePnlProfitText } from '@/hook/common/usePnlProfitText'
import { usePumpTokenHelper } from '@/hook/pump/usePumpTokenHelper'
import { useVirtualLiquidity } from '@/hook/pump/useVirtualLiquidity'
import useTradeTokenStore from '@/store/tradeToken'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import H5Introduction from './H5Introduction'
import PCIntroduction from './PCIntroduction'

function Introduction({ loading }: { loading?: boolean }) {
  const { currentToken } = useTradeTokenStore()

  const { color, percentText } = usePnlProfitText({ initNum: currentToken?.price_change_24h || '0' })

  const { virtualLiquidityValue } = useVirtualLiquidity(currentToken)
  const { market_cap, raising_progress } = usePumpTokenHelper(currentToken)

  const { isApp } = useWindowWidth()
  const props = {
    currentToken,
    loading,
    raising_progress,
    percentText,
    market_cap,
    virtualLiquidityValue,
    color
  }
  return isApp ? <H5Introduction {...props} /> : <PCIntroduction {...props} />
}

export default Introduction
