import { usePumpTrade } from '@/hook/pump/usePumpTrade'
import { SlippageSetting, TradeInputGroup } from '@cetus/design'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import useTransaction from '@cetus/hooks/src/useTransaction'
import { HTextLabelBox } from '@cetus/ui-kit'
import { addComma, d, formatNumber, fromDecimalsAmountFix, getBalanceChanges } from '@cetus/utils'
import { Box, Button, Text, VStack } from '@chakra-ui/react'
import { SUI_DECIMALS } from '@mysten/sui/utils'
import { lazy, useEffect, useMemo, useState } from 'react'

import { useGetMaxAmount } from '@/hook/pump/useGetMaxAmount'
import { useGetPumpToken } from '@/hook/pump/useGetPumpToken'
import { useAccountBalance } from '@cetus/hooks/src/useAccountBalance'
import { useAccountStore } from '@cetus/stores'
import { BalanceChanges, CommonTypeInfo, TransactionStatusType } from '@cetus/types'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { CoinAssist, fromDecimalsAmount, getPackagerConfigs } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus, BondingSwapAmountOptions } from '@cetusprotocol/cetus-sui-pump-sdk'
import { PlaceTradeProps, TradeTabs, TradeType } from './type'

const AggregatorTrade = lazy(() => import('./AggregatorTrade'))
const RegularTrade = lazy(() => import('./RegularTrade'))

function PlaceTrade({ token, refreshFlag, handleRefresh }: PlaceTradeProps) {
  const status = useMemo(() => {
    if (token) {
      return token.status
    }
    return BondingCurveStatus.RAISING
  }, [token?.status])

  const { refreshPumpToken } = useGetPumpToken()
  const [slippage, setSlippage] = useState({ value: 0.5, isOpen: false })
  const { signAndExecuteTransaction } = useTransaction()
  const [tradeType, setTradeType] = useState<TradeType>(TradeType.Buy)
  const [loading, setLoading] = useState(false)
  const { fetchAccountBalance } = useAccountBalance()
  const { currentAccount, onWalletModal } = useAccountStore()
  const { pumpSdk, clmmSdk } = useInitSDK()
  const { buyMaxAmountIn, buyMaxAmountOut, sellMaxAmountIn, sellMaxAmountOut } = useGetMaxAmount(
    token?.liquidity,
    token?.current_sqrt_price,
    token?.init_sqrt_price,
    token?.end_sqrt_price,
    token?.status
  )

  const {
    payCoin,
    receiveCoin,
    payBalance,
    receiveBalance,
    payAmount,
    receiveAmount,
    handleAmountChange,
    calculateSwapResult,
    amountLimit,
    byAmountIn,
    btnText,
    btnDisabled,
    warnInfo,
    calculateLoading,
    refreshPreCalculate
  } = usePumpTrade(
    {
      buyMaxAmountIn,
      buyMaxAmountOut,
      sellMaxAmountIn,
      sellMaxAmountOut
    },
    tradeType === TradeType.Buy,
    slippage.value / 100,
    '0.05',
    token?.token_info_id,
    token?.TokenDetail
  )

  useEffect(() => {
    console.log('🚀 ~ file: index.tsx:80 ~ useEffect ~ refreshFlag:', refreshFlag)
    if (refreshFlag > 0) {
      refreshPreCalculate()
    }
  }, [refreshFlag])

  const onTrade = async () => {
    if (loading) {
      return
    }
    setLoading(true)
    const { clmm_pool } = clmmSdk.sdkOptions
    const { global_config_id, pools_id } = getPackagerConfigs(clmm_pool)
    const is_buy = tradeType === TradeType.Buy
    try {
      const options: BondingSwapAmountOptions = {
        bonding_curve_id: token!.token_info_id,
        token_coin_type: token!.coin_type,
        pay_coin_type: payCoin?.coin_type!,
        swap_result: calculateSwapResult!
      }

      let tx
      tx = await pumpSdk.pumpModule.buildBondingSwapPayload(options)
      if (calculateSwapResult?.do_complete_action) {
        tx = pumpSdk.pumpModule.buildCompleteBondingCurvePayload(
          {
            bonding_curve_id: token!.token_info_id,
            token_metadata_id: token!.TokenDetail.coin_metadata_id,
            sui_metadata_id: envConfigs.sui_coin.id,
            token_coin_type: token?.coin_type,
            clmm_global_config_id: global_config_id,
            clmm_pools_id: pools_id
          },
          tx
        )
      }

      const res = await signAndExecuteTransaction(tx, {
        getShowInfo: (status: TransactionStatusType, balanceChanges?: Record<string, BalanceChanges>) => {
          const info: CommonTypeInfo = {
            iconUrl: token?.TokenDetail?.image,
            toastTitleText: `${tradeType} ${token?.TokenDetail?.name} (${token?.TokenDetail?.symbol})`,
            modalTitleText: `${tradeType} ${token?.TokenDetail?.name} (${token?.TokenDetail?.symbol})`,
            modalDescriptionText: `Trade ${addComma(payAmount)} ${payCoin?.symbol} for ${addComma(receiveAmount)} ${receiveCoin?.symbol}`
          }
          if (status === 'success') {
            let payAmountF = payAmount
            let receiveAmountF = receiveAmount

            if (balanceChanges) {
              payAmountF = getBalanceChanges(balanceChanges, payCoin) || payAmountF
              receiveAmountF = getBalanceChanges(balanceChanges, receiveCoin) || receiveAmountF
            }

            info.modalDescriptionText = `Trade ${addComma(payAmountF)} ${payCoin?.symbol} for ${addComma(receiveAmountF)} ${receiveCoin?.symbol}`
            if (is_buy) {
              info.toastDescriptionContent = `${tradeType} ${addComma(receiveAmountF)} ${token?.TokenDetail?.symbol} successful`
            } else {
              info.toastDescriptionContent = `${tradeType} ${addComma(payAmountF)} ${token?.TokenDetail?.symbol} successful`
            }
          }
          return info
        }
      })
      if (res) {
        handleAmountChange('', true)
      }

      handleRefresh()
    } catch (e) {
      console.error(e, 'trade_error')
      throw new Error('trade error')
    } finally {
      setLoading(false)
    }
  }

  const onSlippageVisible = () => {
    setSlippage(pre => ({ ...pre, isOpen: !pre.isOpen }))
  }

  const onTradeTypeChange = (tab: any) => {
    setTradeType(tab.label)
  }

  return (
    <>
      {status === BondingCurveStatus.CREATED ? (
        <AggregatorTrade slippage={slippage.value} onSlippageVisible={onSlippageVisible} progress={50} />
      ) : (
        <RegularTrade slippage={slippage.value} onSlippageVisible={onSlippageVisible} tradeType={tradeType} onTradeTypeChange={onTradeTypeChange} />
      )}

      <TradeInputGroup
        icon="#icon-a-icon_trade"
        onClick={() => onTradeTypeChange(TradeTabs.find(item => item.label !== tradeType))}
        loading={calculateLoading}
        byAmountIn={byAmountIn}
        from={{
          title: 'You Pay',
          balance: payBalance?.balanceDisplay || '0',
          value: payAmount,
          onChange: value => {
            handleAmountChange(value, true)
          },
          placeholder: '0.0',
          token: payCoin,
          onFocusChange: (focus: boolean) => {
            if (focus && +payAmount && !byAmountIn) {
              handleAmountChange(payAmount, true)
            }
          },
          handleHalfBalance: () => {
            if (payBalance) {
              handleAmountChange(d(payBalance.balanceFormat).div(2).toString(), true, true)
            }
          },
          handleMaxBalance: () => {
            if (payBalance) {
              const amount = d(payBalance.balanceFormat).sub(CoinAssist.isSuiCoin(payCoin?.coin_type || '') ? 0.05 : 0)
              if (d(amount).gt(0)) {
                handleAmountChange(amount.toString(), true, true)
              }
            }
          }
        }}
        to={{
          title: 'You Receive',
          balance: receiveBalance?.balanceDisplay || '0',
          value: receiveAmount,
          onFocusChange: (focus: boolean) => {
            if (focus && +receiveAmount && byAmountIn) {
              handleAmountChange(receiveAmount, false)
            }
          },
          onChange: value => {
            handleAmountChange(value, false, true)
          },
          placeholder: '0.0',
          token: receiveCoin
        }}
      />

      <VStack gap="20px" w="100%" mt="0" borderRadius="20px" border="1px solid" borderColor="border" bg="bg_secondary">
        <Button
          w="calc(100%  + 2px)"
          fontSize="18px"
          fontWeight="600"
          p="16px"
          h="52px"
          borderRadius="16px"
          margin="-1px -1px 0px"
          onClick={() => {
            if (currentAccount) {
              onTrade()
            } else {
              onWalletModal(true)
            }
          }}
          isLoading={loading}
          disabled={btnDisabled}
        >
          {btnText || 'Place Trade'}
        </Button>
        {warnInfo && (
          <Box
            p="10px 18px"
            borderRadius="12px"
            bg="primary_red_opacity.10"
            w="95%"
            mt="-4px"
            mb="12px"
            cursor="pointer"
            onClick={() => {
              console.log('🚀 ~ file: index.tsx:236 ~ PlaceTrade ~ warnInfo:', warnInfo)
              if (+warnInfo.amount) {
                handleAmountChange(fromDecimalsAmountFix(warnInfo.amount, 9), byAmountIn)
              }
            }}
          >
            <Text color="primary_red" fontSize="12px">
              {warnInfo.warnText}
            </Text>
          </Box>
        )}

        {!!payAmount && !!receiveAmount && amountLimit && +amountLimit && (
          <>
            <HTextLabelBox
              isLoading={calculateLoading}
              leftLabel={byAmountIn ? 'Minimum Received' : 'Maximum Input'}
              leftLabelColor="text_paragraph"
              leftLabelFontSize="14px"
              rightValue={`${formatNumber(fromDecimalsAmount(amountLimit || 0, 9).toString() || 0)} ${byAmountIn ? receiveCoin?.symbol : payCoin?.symbol}`}
              rightValueColor="text_caption"
              rightValueFontSize="14px"
              wrapStyle={{
                padding: '0 16px',
                p: {
                  fontWeight: '500'
                }
              }}
            />
            <HTextLabelBox
              isLoading={calculateLoading}
              leftLabel="Fee"
              leftLabelColor="text_paragraph"
              leftLabelFontSize="14px"
              rightValue={`${addComma(fromDecimalsAmountFix(calculateSwapResult?.fee_amount || 0, SUI_DECIMALS))} SUI`}
              rightValueColor="text_caption"
              rightValueFontSize="14px"
              wrapStyle={{
                padding: '0 16px 20px',
                p: {
                  fontWeight: '500'
                }
              }}
            />
          </>
        )}
      </VStack>
      <SlippageSetting
        isOpen={slippage.isOpen}
        onClose={() => setSlippage(pre => ({ ...pre, isOpen: false }))}
        value={slippage.value}
        onChange={value => setSlippage(pre => ({ ...pre, value }))}
      />
    </>
  )
}

export default PlaceTrade
