import { CheckBox, Icon } from '@cetus/ui-kit'
import { Button, HStack, Heading, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

type ExternalAlertProps = {
  link: string
  isOpen: boolean
  onClose: (notAlert: boolean) => void
}

export default function ExternalAlertModel(props: ExternalAlertProps) {
  const { isOpen, onClose, link } = props

  const [notAlert, setNotAlert] = useState<boolean>(false)

  return (
    <Modal isOpen={isOpen} onClose={() => onClose(false)}>
      <ModalOverlay />
      <ModalContent pb="12px" minW={{ base: '', lg: '334px' }}>
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            Tips
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody textAlign="center" id="token_card">
          <VStack w="100%" gap="20px">
            <HStack gap="20px">
              <Icon xlinkHref="#icon-icon_priceupdated" />
              <Text fontSize="14px" color="text_caption" textAlign="start">
                You will be redirected to a 3rd party website, which is not owned by Cetus. Please be careful.
              </Text>
            </HStack>

            <HStack w="100%" p="12px" borderRadius="12px" border="1px solid" borderColor="border">
              <Text>{link} </Text>
            </HStack>

            <HStack>
              <CheckBox
                checked={notAlert}
                onClick={() => {
                  setNotAlert(!notAlert)
                }}
              />
              <Text>Noted. Do not remind again.</Text>
            </HStack>

            <HStack w="100%" mt="12px" justifyContent="space-between">
              <Button
                w="100%"
                fontSize="14px"
                variant="outline"
                onClick={() => {
                  onClose(false)
                }}
              >
                Cancel
              </Button>
              <Button
                w="100%"
                fontSize="14px"
                onClick={() => {
                  window.open(link, '_blank')
                  onClose(notAlert)
                }}
              >
                Continue
              </Button>
            </HStack>
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
