import CurrentChart from '@/components/chart/CurrentChart'
import PumpChart from '@/components/chart/PumpChart'
import { PumpToken } from '@/type/pump'
import { SelectTab } from '@cetus/design'
import Block from '@cetus/design/src/components/common/Block'
import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import { Box } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
interface KLineProps {
  token?: PumpToken
}
type ChartTabsType = 'Pump Chart' | 'Current Price'

function KLine({ token }: KLineProps) {
  console.log('🚀 ~ file: KLine.tsx:16 ~ KLine ~ token:', token)

  const [currentTab, setCurrentTab] = useState<ChartTabsType>('Pump Chart')

  useEffect(() => {
    setCurrentTab((token?.status || 0) >= BondingCurveStatus.MIGRATED ? 'Current Price' : 'Pump Chart')
  }, [token?.status])
  return (
    <>
      {(token?.status || 0) >= BondingCurveStatus.MIGRATED && <ChartTabs currentTab={currentTab} setCurrentTab={setCurrentTab} />}
      <Block>
        <Box h="580px" color="text_caption">
          {currentTab === 'Pump Chart' ? (
            <PumpChart />
          ) : (
            <CurrentChart tokenAddress={token?.coin_type || ''} poolAddress={token?.TokenDetail.clmm_pool || ''} />
          )}
        </Box>
      </Block>
    </>
  )
}

const ChartTabs = ({ currentTab, setCurrentTab }: { currentTab: string; setCurrentTab: (value: ChartTabsType) => void }) => {
  const tabsList = [
    {
      label: 'Pump Chart'
    },
    {
      label: 'Current Price'
    }
  ]
  return (
    <SelectTab
      type="outlineTab"
      tabList={tabsList}
      currentTab={currentTab}
      handleChangeTab={tab => setCurrentTab(tab.label)}
      wrapStyle={{
        w: '100%',
        h: '60px'
      }}
      itemStyle={{
        flex: '1',
        fontSize: '14px',
        margin: '8px'
      }}
    />
  )
}

export default KLine
