import useTradeTokenStore from '@/store/tradeToken'
import { Box } from '@chakra-ui/react'
import { useEffect, useRef, useState } from 'react'
import TVChartContainer from './TVChartContainer'

export default function PumpChart() {
  const { currentToken } = useTradeTokenStore()
  const chartTimerRef = useRef(null)
  const subscriberUIDRef = useRef(null)
  const [currentPriceData, setCurrentPriceData] = useState<any>(null)

  useEffect(() => {
    console.log('🚀 ~ file: PumpChart.tsx:16 ~ PumpChart ~ currentToken:', currentToken)
  }, [currentToken])

  const changeChartTimer = (value: any) => {
    if (!value && chartTimerRef.current) {
      clearInterval(chartTimerRef.current)
      chartTimerRef.current = null
    } else {
      chartTimerRef.current = value
    }
  }

  const changeSubscriberUIDRef = (value: any) => {
    subscriberUIDRef.current = value
  }

  // 可以接收k线接口最后一个点的数据，也就是最新价格
  const handleChangeLastPrice = (value: any) => {
    console.log('🚀 ~ file: PumpChart.tsx:29 ~ handleChangeLastPrice ~ value:', value)
    setCurrentPriceData(value)
  }

  // 用deepbook数据测试时候的值
  // const symbol = 'DEEP-SUI'
  // const id = '0xb663828d6217467c8a1838a03793da896cbe745b150ebd57d82f814ca579fc22'

  // Ethan给的可调用的值
  // const symbol = 'TOKEN_SYMBOL'
  // const id = '0x3c247887e18ade26bd1896d1c006ac8126747031ffedcc189b147dae3d180d73'

  useEffect(() => {
    return () => {
      changeChartTimer(null)
    }
  }, [])

  return (
    <Box w="100%" h="100%">
      {currentToken?.TokenDetail.ticker && currentToken?.token_info_id && (
        <TVChartContainer
          symbol={currentToken?.TokenDetail.ticker}
          id={currentToken?.token_info_id}
          chartTimerRef={chartTimerRef}
          changeChartTimer={changeChartTimer}
          subscriberUIDRef={subscriberUIDRef}
          changeSubscriberUIDRef={changeSubscriberUIDRef}
          changeLastPrice={handleChangeLastPrice}
          end_time={currentToken.TokenDetail.list_on_dex_timestamp}
        />
      )}
    </Box>
  )
}
