import { AddressUnderline } from '@cetus/design'
import { CopyButton, Icon } from '@cetus/ui-kit'
import { addressAbridge } from '@cetus/utils'
import { HStack, Skeleton, Text } from '@chakra-ui/react'
import { useNavigate } from 'react-router-dom'

function Address({ label, address, url, isLoaded, jumpUrl }: { address: string; label: string; url: string; jumpUrl?: string; isLoaded?: boolean }) {
  const navigate = useNavigate()
  return (
    <Skeleton isLoaded={isLoaded}>
      <HStack h="20px" lineHeight="20px" gap={{ base: '2px', lg: '4px' }}>
        <Text color="text_paragraph" fontSize="14px">
          {label}:
        </Text>
        {jumpUrl ? (
          <AddressUnderline
            address={address}
            color="text_paragraph"
            fontSize="14px"
            onClickLink={() => {
              if (jumpUrl) {
                navigate(jumpUrl)
              }
            }}
          />
        ) : (
          <Text color="text_paragraph" fontSize="14px" fontWeight="400">
            {addressAbridge(address)}
          </Text>
        )}

        <CopyButton text={address} />
        <Icon xlinkHref="#icon-icon_link" onClick={() => window.open(url)} />
      </HStack>
    </Skeleton>
  )
}

export default Address
